-- Initial unreleased schema, generated by tools/generate_migrations.py.
-- Execute statements under the migration runner exclusive lock.

CREATE TABLE import_batches (
    id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    created_at BIGINT NOT NULL,
    requested_by VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    input_manifest_json LONGTEXT NOT NULL,
    state VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    committed_at BIGINT,
    result_json LONGTEXT,
    PRIMARY KEY (id),
    CHECK (state IN ('previewed','committed','failed')),
    CHECK (length(id) = 36),
    CHECK (length(requested_by) = 36),
    CHECK (length(state) <= 32)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE revocations (
    id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    version BIGINT NOT NULL,
    issuer_ca_key_generation_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    serial_hex VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    certificate_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    revoked_at BIGINT NOT NULL,
    reason VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    source VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    change_generation BIGINT NOT NULL,
    PRIMARY KEY (id),
    UNIQUE (issuer_ca_key_generation_id, serial_hex),
    CHECK (reason IN ('unspecified','keyCompromise','caCompromise','affiliationChanged','superseded','cessationOfOperation','privilegeWithdrawn','aACompromise')),
    CHECK (length(id) = 36),
    CHECK (version >= 0),
    CHECK (length(issuer_ca_key_generation_id) = 36),
    CHECK (length(serial_hex) BETWEEN 1 AND 40),
    CHECK ((length(serial_hex) = 1 OR substr(serial_hex,1,1) <> '0')),
    CHECK (serial_hex REGEXP '^[0-9a-f]+$'),
    CHECK (length(certificate_id) = 36),
    CHECK (length(reason) <= 32),
    CHECK (length(source) <= 32),
    CHECK (change_generation >= 0)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE revocation_revisions (
    id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    created_at BIGINT NOT NULL,
    revocation_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    revision_no BIGINT NOT NULL,
    previous_values_json LONGTEXT NOT NULL,
    new_values_json LONGTEXT NOT NULL,
    justification LONGTEXT NOT NULL,
    actor_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    source_import_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    PRIMARY KEY (id),
    UNIQUE (revocation_id, revision_no),
    CHECK (length(id) = 36),
    CHECK (length(revocation_id) = 36),
    CHECK (revision_no >= 0),
    CHECK (length(actor_id) = 36),
    CHECK (length(source_import_id) = 36)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE ca_takeovers (
    id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    created_at BIGINT NOT NULL,
    updated_at BIGINT NOT NULL,
    version BIGINT NOT NULL,
    ca_key_generation_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    state VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    history_assertion VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    previous_max_number_hex VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin,
    external_issuer_stopped_at BIGINT,
    confirmed_by VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    confirmed_at BIGINT,
    evidence_json LONGTEXT NOT NULL,
    PRIMARY KEY (id),
    CHECK (state IN ('pending','confirmed')),
    CHECK (length(id) = 36),
    CHECK (version >= 0),
    CHECK (length(ca_key_generation_id) = 36),
    CHECK (length(state) <= 32),
    CHECK (length(history_assertion) <= 32),
    CHECK (length(previous_max_number_hex) BETWEEN 1 AND 40),
    CHECK ((length(previous_max_number_hex) = 1 OR substr(previous_max_number_hex,1,1) <> '0')),
    CHECK (previous_max_number_hex REGEXP '^[0-9a-f]+$'),
    CHECK (length(confirmed_by) = 36)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE crl_states (
    ca_key_generation_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    max_reserved_number_hex VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    revocation_generation BIGINT NOT NULL,
    published_crl_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    next_publish_at BIGINT,
    publication_state VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    signing_ca_certificate_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    updated_at BIGINT NOT NULL,
    version BIGINT NOT NULL,
    PRIMARY KEY (ca_key_generation_id),
    CHECK (publication_state IN ('inactive','active','closed')),
    CHECK (length(ca_key_generation_id) = 36),
    CHECK (length(max_reserved_number_hex) BETWEEN 1 AND 40),
    CHECK ((length(max_reserved_number_hex) = 1 OR substr(max_reserved_number_hex,1,1) <> '0')),
    CHECK (max_reserved_number_hex REGEXP '^[0-9a-f]+$'),
    CHECK (revocation_generation >= 0),
    CHECK (length(published_crl_id) = 36),
    CHECK (length(publication_state) <= 32),
    CHECK (length(signing_ca_certificate_id) = 36),
    CHECK (version >= 0)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;

CREATE TABLE crl_documents (
    id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    created_at BIGINT NOT NULL,
    ca_key_generation_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    number_hex VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin,
    der_sha256 VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    der LONGBLOB NOT NULL,
    this_update BIGINT NOT NULL,
    next_update BIGINT,
    covered_generation BIGINT,
    origin VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    source_import_id VARCHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    PRIMARY KEY (id),
    UNIQUE (der_sha256),
    CHECK (origin IN ('generated','imported')),
    CHECK (origin <> 'generated' OR (number_hex IS NOT NULL AND next_update IS NOT NULL AND covered_generation IS NOT NULL)),
    CHECK (next_update IS NULL OR next_update > this_update),
    CHECK (length(id) = 36),
    CHECK (length(ca_key_generation_id) = 36),
    CHECK (length(number_hex) BETWEEN 1 AND 40),
    CHECK ((length(number_hex) = 1 OR substr(number_hex,1,1) <> '0')),
    CHECK (number_hex REGEXP '^[0-9a-f]+$'),
    CHECK (length(der_sha256) = 64),
    CHECK (covered_generation >= 0),
    CHECK (length(origin) <= 32),
    CHECK (length(source_import_id) = 36)
) ENGINE=InnoDB DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
